import{games,themes,fonts,initial,makeWord,uid,escape as e,validate,validateProject,parseText,persist,restore}from'./core/model.js';
import{mountGame}from'./core/runtime.js';
let p=initial(),tab='project',mode='edit',selected=null,history=[],future=[],runtime=null,saveTick,toastTick,mobileOpen=false,dbError=false,objectPage=0;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],modal=$('#modal');
const nav=[['project','▧','Проект'],['dictionary','≡','Словарь'],['age','♧','Возраст и сложность'],['catalog','▦','Каталог игр'],['world','◈','Игровой мир'],['assets','♙','Персонажи и ассеты'],['tasks','☷','Задания'],['style','Aa','Стиль заданий'],['final','⚑','Финальные экраны'],['rules','♡','Жизни, таймер, баллы'],['controls','⌘','Кнопки управления'],['export','↗','Экспорт']];
function notify(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTick);toastTick=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function snapshot(){history.push(JSON.stringify(p));if(history.length>50)history.shift();future=[];}
function changed(){p.updated=Date.now();$('.save-status').textContent='Сохраняем…';clearTimeout(saveTick);saveTick=setTimeout(async()=>{try{await persist(p);$('.save-status').textContent='Все изменения сохранены';}catch{dbError=true;$('.save-status').textContent='Скачайте проект: хранилище недоступно';}},450);updateCounts();}
function updateCounts(){let n=p.words.length;$('#counts').innerHTML=`<span>Слов: ${n}</span><span>Заданий: ${n}</span><span>Объектов: ${p.objects.length}</span><span>${(new Blob([JSON.stringify(p)]).size/1024).toFixed(1)} КБ</span>`;$('#undo').disabled=!history.length;$('#redo').disabled=!future.length;}
function commit(fn,redraw=true){snapshot();fn();changed();if(redraw){renderPanel();renderStage();renderCards();}}
function gameCard(g){let art={garden:'🌷 🌼 🌱',catch:'☁️ А ☁️',letters:'Б У К',maze:'⌘ ⌘ ⌘',detective:'🔎 📜',space:'🪐 🚀',sprint:'А ϟ Я',safe:'🔒 А ✦'}[g.id];return `<button class="game-card ${p.game===g.id?'active':''}" data-game="${g.id}" style="--card-color:${g.color}"><div class="mini-scene"><span class="mini-art">${art}</span></div><span class="game-badge">${g.age}</span>${p.game===g.id?'<span class="chosen-badge">✓</span>':''}<h3>${g.name}</h3><p>${g.tag}</p></button>`;}
function render(){document.body.classList.toggle('view-only',false);$('#app').innerHTML=`<header class="topbar"><div class="brand"><span class="brand-mark">с</span><div><b>словник<span style="color:#8eaa7e">.</span></b><small>МАСТЕРСКАЯ СЛОВАРНЫХ ИГР</small></div></div><div class="project-heading"><input id="projectTitle" value="${e(p.title)}" aria-label="Название проекта"><span class="save-status">Все изменения сохранены</span></div><div class="header-actions"><button class="btn" id="load">↥ <span class="load-label">Загрузить</span></button><button class="btn" id="save">↓ <span class="save-label">Сохранить проект</span></button><button class="btn primary" id="exportBtn">↗ Экспорт игры</button></div></header><div class="layout"><nav class="sidebar" aria-label="Разделы редактора"><div class="side-label">МАСТЕРСКАЯ</div>${nav.map(([id,icon,label],i)=>`${i===9?'<div class="side-separator"></div>':''}<button title="${label}" class="nav-item ${tab===id?'active':''}" data-tab="${id}"><span class="nav-icon">${icon}</span><span class="nav-text">${label}</span>${tab===id?'<span class="nav-dot"></span>':''}</button>`).join('')}<div class="help-card"><b>✧ Маленькая подсказка</b><p>Загрузите слова один раз.<br>Меняйте игры — словарь<br>останется с вами.</p><button id="help">Как это работает ↗</button></div><div class="sidebar-bottom">СОЗДАНО ДЛЯ ТЕХ, КТО УЧИТ ♡</div></nav><aside class="inspector ${mobileOpen?'mobile-open':''}" id="panel"></aside><main class="workspace"><div class="workspace-heading"><div><div class="breadcrumb">Моя мастерская <span style="padding:0 7px">/</span> Новый мир знаний</div><h1>Здесь слова оживают<span style="color:#7c9a6a">.</span></h1><p>Немного фантазии — и ваш словарь превращается в приключение.</p></div><button class="btn soft" id="play">▷ Играть</button></div><div class="stage-toolbar"><div class="segmented mode-switch"><button data-mode="edit" class="${mode==='edit'?'active':''}">✎ Редактор</button><button data-mode="preview" class="${mode==='preview'?'active':''}">◉ Предпросмотр</button><button data-mode="test" class="${mode==='test'?'active':''}">▷ Тест</button></div><div class="toolbar-right"><button id="undo" class="icon-button" title="Отменить (Ctrl+Z)">↶</button><button id="redo" class="icon-button" title="Повторить (Ctrl+Shift+Z)">↷</button><span class="zoom-label" style="padding:0 8px">16:9</span><button class="icon-button" id="expand" title="Развернуть рабочую область">⛶</button></div></div><div class="stage-wrap"><div id="scene" class="game-scene"></div><div class="scene-caption"><span><i class="green-dot"></i><span id="sceneStatus">Сцена 1 · ${games.find(g=>g.id===p.game).name}</span></span><span class="key-hint">1200 × 675 · адаптивный холст</span><span id="rounds">${Math.ceil(p.words.length/6)} раунда</span></div></div><div class="objects-bar"><span id="selectionLabel">✧ <b>Ваш мир готов к творчеству</b> · Выберите объект на сцене</span><button class="btn soft" id="addObject" style="padding:7px 10px;font-size:9px">＋ Добавить объект</button></div><section><div class="section-heading"><div><h2>Одна история — разные приключения</h2><p>Выберите механику. Мы бережно перенесём все ваши слова.</p></div><button id="allGames">Все 8 игр ↗</button></div><div class="game-cards" id="cards"></div></section></main></div><footer class="statusbar"><div class="status-left" id="counts"></div><span class="copyright">Все права защищены и принадлежат Гальмиз Марии Александровне</span><span>Словник · 1.0</span></footer>`;
$('#projectTitle').addEventListener('change',ev=>commit(()=>p.title=ev.target.value||'Мой проект',false));$('#save').onclick=saveProject;$('#load').onclick=loadProject;$('#exportBtn').onclick=exportDialog;$('#help').onclick=help;$('#allGames').onclick=catalog;$('#play').onclick=()=>setMode('test');$('#addObject').onclick=()=>selectTab('assets');$('#expand').onclick=()=>{document.body.classList.toggle('view-only');};$('#undo').onclick=undo;$('#redo').onclick=redo;$$('[data-tab]').forEach(b=>b.onclick=()=>selectTab(b.dataset.tab));$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));renderPanel();renderStage();renderCards();updateCounts();}
function selectTab(id){if(tab===id&&window.innerWidth<761)mobileOpen=!mobileOpen;else mobileOpen=true;tab=id;$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));$('#panel').classList.toggle('mobile-open',mobileOpen);renderPanel();if(id==='catalog')catalog();}
function setMode(m){mode=m;$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));renderStage();if(m==='test')runtime.start();}
function renderCards(){$('#cards').innerHTML=games.map(gameCard).join('');$('#cards').querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>switchGame(b.dataset.game));}
function switchGame(id){commit(()=>{p.game=id;if(id==='safe'){if(p.titleText==='Пусть знания расцветают!')p.titleText='Взломай словарный сейф!';if(p.instruction==='Выбирай правильные слова и оживи волшебный сад.')p.instruction='Запомни слово, восстанови секретные буквы и открой все замки.';if(p.winText==='Твой сад расцвёл!')p.winText='Все сейфы открыты!';}if(id==='garden'){if(p.titleText==='Взломай словарный сейф!')p.titleText='Пусть знания расцветают!';if(p.instruction==='Запомни слово, восстанови секретные буквы и открой все замки.')p.instruction='Выбирай правильные слова и оживи волшебный сад.';if(p.winText==='Все сейфы открыты!')p.winText='Твой сад расцвёл!';}if(id==='space')p.theme='space';if(id==='detective')p.theme='lab';if(id==='garden'&&p.theme==='space')p.theme='forest';});notify('Игра изменена. Словарь и правки сохранены.');}
const field=(label,key,type='text',extra='')=>`<div class="field"><label>${label}</label><input data-prop="${key}" type="${type}" value="${e(p[key])}" ${extra}></div>`;
function themePicker(){return `<div class="theme-grid">${themes.map(t=>`<button class="theme-tile ${p.theme===t.id?'active':''}" data-theme="${t.id}"><div class="theme-swatch" style="background:${t.sky}">${t.icon}</div>${t.name}</button>`).join('')}</div>`;}
function renderPanel(){let title=nav.find(n=>n[0]===tab)[2],intro='',body='';
if(tab==='project'){title='Начнём с идеи';intro='Создайте свой маленький мир, в котором хочется узнавать новое.';body=`${field('Название проекта','title')}<div class="field"><label>Название на игровой сцене</label><textarea rows="2" data-prop="titleText">${e(p.titleText)}</textarea></div><div class="field"><label>Короткая инструкция</label><textarea rows="3" data-prop="instruction">${e(p.instruction)}</textarea></div><div class="divider"></div><div class="field"><label>Атмосфера игры <span style="font-weight:400;color:#97a18e">5 миров</span></label>${themePicker()}</div><div class="divider"></div><div class="notice">✿ <b>Сначала слова — потом магия</b><br>Добавьте свой словарь, а Словник превратит его в игровые задания.</div><button class="btn soft full-width" data-go="dictionary" style="margin-top:12px">Перейти к словарю →</button>`;}
if(tab==='dictionary'){intro='Один словарь для всех приключений. Импортируйте список или добавьте слова вручную.';body=`<button class="btn soft full-width" id="importWords">↥ Загрузить словарь</button><div class="asset-size" style="margin-top:7px">TXT · CSV · XLSX · JSON · UTF-8</div><div class="field"><label>Добавить слова</label><textarea id="wordInput" rows="5" placeholder="берёза\nкарандаш\nмолоко"></textarea><small>Одна строка — одно слово. Поддерживаются запятые и точка с запятой.</small></div><button class="btn primary full-width" id="addWords">＋ Добавить в словарь</button><div class="divider"></div><span class="word-count">В вашем словаре: ${p.words.length} слов</span><div class="word-list">${p.words.map(w=>`<span class="word-chip">${e(w.word)}<button data-delete-word="${w.id}" aria-label="Удалить ${e(w.word)}">×</button></span>`).join('')}</div><button class="btn full-width" data-go="tasks">Проверить задания →</button>`;}
if(tab==='age'){intro='Возраст меняет темп и оформление. Все слова и ручные правки сохраняются.';body=['6–9 лет · 1–3 классы','9–12 лет · 4–6 классы','12–15 лет · 7–9 классы','15–18 лет · 10–11 классы'].map((a,i)=>`<button class="btn full-width ${p.age===i?'soft':''}" data-age="${i}" style="justify-content:space-between;margin:5px 0">${a}<span>${p.age===i?'✓':'→'}</span></button>`).join('')+`<div class="divider"></div><div class="notice">${['Крупные слова, спокойный темп и сказочный мир. Таймер выключен.','Приключения, коллекции и небольшие открытия на каждом шаге.','Орфографические расследования и головоломки.','Сдержанный стиль, ввод целиком и задания на скорость.'][p.age]}</div>`;}
if(tab==='catalog'){intro='Восемь игровых механик работают с вашим словарём.';body=games.map(g=>`<button class="btn ${p.game===g.id?'soft':''} full-width" data-game="${g.id}" style="justify-content:start;margin-bottom:7px">${g.icon} ${g.name}</button>`).join('');}
if(tab==='world'){intro='Каждый объект хранит положение относительно сцены 1200 × 675.';body=`<div class="field"><label>Выберите атмосферу</label>${themePicker()}</div><button id="backgroundUpload" class="btn full-width">↥ Свой фон</button>${p.background?'<button class="btn full-width" id="clearBackground" style="margin-top:6px">Вернуть встроенный фон</button>':''}<div class="divider"></div>${objectSettings()}`;}
if(tab==='assets'){intro='Добавляйте отдельные элементы мира или свои PNG, JPEG, WebP и GIF.';let t=themes.find(t=>t.id===p.theme);body=`<div class="asset-list">${[t.hero,...t.objects,'🌱','💎','🗝️'].map(s=>`<button class="asset-button" data-emoji="${s}" title="Добавить ${s}">${s}</button>`).join('')}</div><div class="divider"></div><button class="btn soft full-width" id="assetUpload">↥ Загрузить изображение / GIF</button><label class="checkline">Сжимать статичные изображения <input id="optimize" type="checkbox" checked></label><small class="asset-size">GIF сохраняется без изменений, чтобы не потерять анимацию.</small><div class="asset-list" style="margin-top:15px">${p.assets.map(a=>`<button class="asset-button" data-asset="${a.id}" title="${e(a.name)}"><img src="${e(a.data)}" alt="${e(a.name)}"></button>`).join('')}</div><div class="divider"></div>${objectSettings()}`;}
if(tab==='tasks'){intro='Ошибочные варианты созданы автоматически. Проверьте их перед экспортом.';body=`<div class="notice">Проверено: ${p.words.filter(w=>w.approved).length} / ${p.words.length}<br>Редактируйте варианты и отмечайте готовые задания.</div><button class="btn soft full-width" id="review" style="margin-top:12px">Открыть проверку заданий →</button><div class="field"><label>Вопрос для выбора ответа</label><textarea data-prop="question" rows="3">${e(p.question)}</textarea></div><button class="btn full-width" id="assign">Привязать объекты автоматически</button>`;}
if(tab==='style'){intro='Настройки применяются ко всем заданиям и сохраняются в экспорте.';body=`<div class="field"><label>Шрифт <span>32 варианта</span></label><select data-prop="font">${fonts.map(f=>`<option ${p.font===f?'selected':''}>${f}</option>`).join('')}</select><small>Автономная игра использует установленный шрифт или Arial. Внешние шрифты не загружаются.</small></div>${field('Размер заголовка','fontSize','number','min="16" max="70"')}<div class="field"><label>Акцент игры</label><div class="swatches">${['#286b54','#406f96','#785b92','#b4744d','#b75b77'].map(c=>`<button data-accent="${c}" style="background:${c}" aria-label="Выбрать цвет ${c}"></button>`).join('')}<input data-prop="accent" type="color" value="${p.accent}" style="width:30px;height:28px;padding:2px"></div></div>`;}
if(tab==='final'){intro='Сделайте финал тёплым и запоминающимся. Статистика появится автоматически.';body=field('Заголовок победы','winText')+field('Заголовок поражения','loseText')+'<div class="notice">В конце игры: верные ответы, ошибки, время и баллы. Кнопка «Играть ещё раз» запускает новое прохождение.</div>';}
if(tab==='rules'){intro='Настройте комфортный ритм для своих учеников.';body=field('Жизни · 0 — без ограничений','lives','number','min="0" max="99"')+field('Таймер · секунды, 0 — выключен','timer','number','min="0" max="3600"')+field('Баллы за правильный ответ','points','number','min="1" max="1000"')+`<label class="checkline">Звуковые эффекты <input data-prop="sound" type="checkbox" ${p.sound?'checked':''}></label><div class="field"><label>Громкость</label><input data-prop="volume" type="range" min="0" max="100" value="${p.volume}"></div><label class="checkline">Уменьшить анимацию <input data-prop="reduceMotion" type="checkbox" ${p.reduceMotion?'checked':''}></label>`;}
if(tab==='controls'){intro='Игра доступна для мыши, сенсорного экрана и клавиатуры.';body='<div class="notice"><b>Tab</b> — следующий элемент<br><b>Enter / Пробел</b> — выбрать ответ<br><b>Enter</b> — отправить ввод<br><br><b>В редакторе:</b><br>Ctrl / ⌘ + Z — отмена<br>Ctrl / ⌘ + Shift + Z — повтор<br>Стрелки — сдвинуть выбранный объект<br>Delete — удалить объект</div><div class="divider"></div><button class="btn soft full-width" id="testGame">Проверить игру →</button>';}
if(tab==='export'){intro='Только игра — без панелей редактора и служебного футера.';body=`<button class="btn primary full-width" id="downloadHTML">↓ Скачать HTML-файл</button><button class="btn full-width" id="lighten" style="margin-top:10px">✧ Облегчить код для Genially</button><button class="btn full-width" id="copyGenially" style="margin-top:10px">⌘ Скопировать код Genially</button><div class="divider"></div><div class="notice">HTML работает автономно. Для Genially надёжнее разместить игру на GitHub Pages и вставить ссылку через iframe.</div><button class="btn full-width" id="instructions" style="margin-top:12px">Инструкция по встраиванию ↗</button><div class="divider"></div><button class="btn full-width" id="newProject">＋ Новый проект</button>`;}
$('#panel').innerHTML=`<div class="panel-kicker">ВАША ИСТОРИЯ</div><h2 class="panel-title">${title}</h2><p class="panel-intro">${intro}</p>${body}`;wirePanel();}
function objectSettings(){let o=p.objects.find(x=>x.id===selected);if(!o)return'<div class="empty">Нажмите на объект в режиме редактирования, чтобы изменить размер, поворот, прозрачность и слой.</div>';return`<div class="field-label">Выбранный объект <span>${e(o.emoji||'Изображение')}</span></div>${['x','y','size','rotation','opacity','layer'].map((k,i)=>`<div class="field"><label>${['Положение X, %','Положение Y, %','Размер','Поворот, °','Непрозрачность','Слой'][i]}</label><input type="number" data-object-prop="${k}" value="${o[k]||0}" step="${k==='opacity'?'.1':'1'}" min="${k==='rotation'?'-180':'0'}" max="${k==='opacity'?'1':k==='rotation'?'180':k==='size'?'300':'100'}"></div>`).join('')}<div class="field"><label>Привязанное задание</label><select id="objectWord"><option value="">Декоративный объект</option>${p.words.map(w=>`<option value="${w.id}" ${w.id===o.wordId?'selected':''}>${e(w.word)}</option>`).join('')}</select></div><label class="checkline">Заблокировать перемещение <input id="objectLock" type="checkbox" ${o.locked?'checked':''}></label><button class="btn full-width" id="deleteObject">Удалить объект</button>`;}
function wirePanel(){document.querySelectorAll('[data-prop]').forEach(el=>{el.addEventListener('change',()=>{snapshot();let key=el.dataset.prop;p[key]=el.type==='checkbox'?el.checked:el.type==='number'||el.type==='range'?Number(el.value):el.value;changed();renderStage();if(key==='title')$('#projectTitle').value=p.title;});if(el.tagName==='TEXTAREA'){el.addEventListener('focus',snapshot);el.addEventListener('input',()=>{p[el.dataset.prop]=el.value;changed();renderStage();});}});$$('[data-go]').forEach(b=>b.onclick=()=>selectTab(b.dataset.go));$$('[data-theme]').forEach(b=>b.onclick=()=>commit(()=>{p.theme=b.dataset.theme;delete p.background;}));$$('#panel [data-game]').forEach(b=>b.onclick=()=>switchGame(b.dataset.game));$$('[data-accent]').forEach(b=>b.onclick=()=>commit(()=>p.accent=b.dataset.accent));$$('[data-age]').forEach(b=>b.onclick=()=>commit(()=>{p.age=+b.dataset.age;p.fontSize=[34,30,27,25][p.age];p.timer=0;p.theme=['forest','ocean','castle','space'][p.age];}));
const click=(id,fn)=>{let b=$(id);if(b)b.onclick=fn;};click('#addWords',()=>{let words=parseText($('#wordInput').value);appendWords(words);});click('#importWords',importWords);$$('[data-delete-word]').forEach(b=>b.onclick=()=>commit(()=>{p.words=p.words.filter(w=>w.id!==b.dataset.deleteWord);p.objects=p.objects.filter(o=>o.wordId!==b.dataset.deleteWord);}));click('#review',reviewTasks);click('#assign',()=>commit(()=>{p.words.forEach((w,i)=>{if(!p.objects.some(o=>o.wordId===w.id))p.objects.push(newObject('🌼',w.id,i));});notify('Все задания привязаны к объектам.');}));click('#backgroundUpload',()=>uploadAsset(true));click('#clearBackground',()=>commit(()=>delete p.background));click('#assetUpload',()=>uploadAsset(false));$$('[data-emoji]').forEach(b=>b.onclick=()=>addObject({emoji:b.dataset.emoji}));$$('[data-asset]').forEach(b=>b.onclick=()=>addObject({assetId:b.dataset.asset}));$$('[data-object-prop]').forEach(el=>el.onchange=()=>commit(()=>{let o=p.objects.find(o=>o.id===selected);o[el.dataset.objectProp]=Number(el.value);}));click('#deleteObject',deleteObject);if($('#objectWord'))$('#objectWord').onchange=ev=>commit(()=>p.objects.find(o=>o.id===selected).wordId=ev.target.value);if($('#objectLock'))$('#objectLock').onchange=ev=>commit(()=>p.objects.find(o=>o.id===selected).locked=ev.target.checked);click('#downloadHTML',()=>downloadGame(false));click('#copyGenially',copyGenially);click('#lighten',lighten);click('#instructions',embedHelp);click('#newProject',newProject);click('#testGame',()=>setMode('test'));}
function newObject(emoji,wordId='',i=0){return{id:uid(),emoji,wordId,x:20+(i%6)*12,y:54+Math.floor(i/6)%2*22,size:50,opacity:1,rotation:0,layer:2,locked:false};}
function addObject(props){commit(()=>{let o={...newObject('🌼'),...props,x:50,y:60};p.objects.push(o);objectPage=Math.floor((p.objects.length-1)/12);selected=o.id;});notify('Объект добавлен. Перетащите его по сцене.');}
function deleteObject(){if(!selected)return;commit(()=>{p.objects=p.objects.filter(o=>o.id!==selected);selected=null;});}
function renderStage(){objectPage=Math.min(objectPage,Math.max(0,Math.ceil(p.objects.length/12)-1));runtime?.destroy();runtime=mountGame($('#scene'),structuredClone(p),{edit:mode==='edit',page:objectPage});$('#sceneStatus').textContent='Сцена 1 · '+games.find(g=>g.id===p.game).name;$('#rounds').innerHTML=`<button class="icon-button" id="prevPage" title="Предыдущая страница объектов" style="width:20px;height:20px;font-size:12px" ${objectPage===0?'disabled':''}>‹</button> ${objectPage+1} / ${Math.max(1,Math.ceil(p.objects.length/12))} <button class="icon-button" id="nextPage" title="Следующая страница объектов" style="width:20px;height:20px;font-size:12px" ${objectPage>=Math.ceil(p.objects.length/12)-1?'disabled':''}>›</button>`;$('#prevPage').onclick=()=>{objectPage--;renderStage();};$('#nextPage').onclick=()=>{objectPage++;renderStage();};if(mode==='edit')wireDrag();if(selected){let o=p.objects.find(o=>o.id===selected);if(o)$('#selectionLabel').innerHTML=`✎ <b>Объект выбран</b> · ${e(o.emoji||'Изображение')} · X ${Math.round(o.x)} / Y ${Math.round(o.y)}`;}else $('#selectionLabel').innerHTML='✧ <b>Ваш мир готов к творчеству</b> · Выберите объект на сцене';}
function wireDrag(){$$('#scene [data-object]').forEach(el=>{el.classList.toggle('selected',el.dataset.object===selected);el.addEventListener('pointerdown',ev=>{let o=p.objects.find(o=>o.id===el.dataset.object);selected=o.id;$$('#scene [data-object]').forEach(b=>b.classList.toggle('selected',b===el));if(tab!=='assets'&&tab!=='world')selectTab('world');else renderPanel();if(o.locked)return;ev.preventDefault();snapshot();let rect=$('#scene').getBoundingClientRect();let x=ev.clientX,y=ev.clientY,ox=o.x,oy=o.y,originalSize=o.size,resizing=ev.target.dataset.resize==='true';el.setPointerCapture(ev.pointerId);el.onpointermove=ev=>{if(resizing){o.size=Math.max(16,Math.min(250,originalSize+(ev.clientX-x)/rect.width*1200));el.style.fontSize=o.size/12+'cqw';el.style.width=o.size/12+'cqw';el.style.height=o.size/10+'cqw';return;}o.x=Math.max(2,Math.min(98,ox+(ev.clientX-x)/rect.width*100));o.y=Math.max(2,Math.min(98,oy+(ev.clientY-y)/rect.height*100));el.style.left=o.x+'%';el.style.top=o.y+'%';};el.onpointerup=()=>{el.onpointermove=null;changed();renderPanel();renderStage();};});});}
function appendWords(words){let existing=new Set(p.words.map(w=>w.word.toLowerCase()));let fresh=words.filter(w=>{let k=w.word.toLowerCase();if(existing.has(k))return false;existing.add(k);return true;});if(!fresh.length)return notify('Новых слов нет: список пуст или содержит дубликаты.');commit(()=>{fresh.forEach((w,i)=>p.objects.push(newObject('🌼',w.id,p.words.length+i)));p.words.push(...fresh);});notify(`Добавлено слов: ${fresh.length}. Пропущено дубликатов: ${words.length-fresh.length}.`);}
function undo(){if(!history.length)return;future.push(JSON.stringify(p));p=JSON.parse(history.pop());selected=null;changed();render();}
function redo(){if(!future.length)return;history.push(JSON.stringify(p));p=JSON.parse(future.pop());selected=null;changed();render();}
function openDialog(title,body,actions=''){modal.innerHTML=`<button class="close-modal" aria-label="Закрыть">×</button><h2>${title}</h2><div class="modal-body">${body}</div><div class="modal-actions">${actions}</div>`;modal.querySelector('.close-modal').onclick=()=>modal.close();if(!modal.open)modal.showModal();}
function catalog(){openDialog('Выберите своё приключение','<p>Ваши слова уже ждут внутри каждой игры.</p><div class="catalog-dialog">'+games.map(gameCard).join('')+'</div>');modal.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>{switchGame(b.dataset.game);modal.close();});}
function reviewTasks(){let draft=structuredClone(p.words);openDialog('Сначала проверим слова',`<p>Слева — правильное написание. Справа — отвлекающий вариант. Проверьте каждую пару; пояснение ученик увидит после ответа.</p><div class="task-labels"><span>Правильно</span><span>С ошибкой</span><span>✓</span></div>${draft.map((w,i)=>`<div class="task-row"><input data-task="${i}" data-key="word" value="${e(w.word)}" aria-label="Правильное слово ${i+1}"><input data-task="${i}" data-key="wrong" value="${e(w.wrong)}" aria-label="Ошибочный вариант ${i+1}"><input data-task="${i}" data-key="approved" type="checkbox" ${w.approved?'checked':''} aria-label="Проверено ${i+1}"></div><details class="task-detail"><summary class="asset-size">Подсказка и объяснение</summary><input data-task="${i}" data-key="hint" value="${e(w.hint)}" placeholder="Подсказка"><input data-task="${i}" data-key="explanation" value="${e(w.explanation)}" placeholder="Объяснение после ответа"></details>`).join('')}`,`<button class="btn" id="approveAll">Все варианты проверены</button><button class="btn primary" id="saveTasks">Сохранить</button>`);modal.querySelectorAll('[data-task]').forEach(el=>el.oninput=()=>draft[+el.dataset.task][el.dataset.key]=el.type==='checkbox'?el.checked:el.value);$('#approveAll').onclick=()=>{draft.forEach(w=>w.approved=true);modal.querySelectorAll('input[type=checkbox]').forEach(el=>el.checked=true);};$('#saveTasks').onclick=()=>{if(draft.some(w=>!w.word.trim()||!w.wrong.trim()||w.word.trim().toLowerCase()===w.wrong.trim().toLowerCase()))return notify('Проверьте пары: варианты должны быть непустыми и различаться.');commit(()=>p.words=draft);modal.close();notify('Задания сохранены.');};}
function download(content,name,type='application/json'){let url=URL.createObjectURL(new Blob([content],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function saveProject(){download(JSON.stringify(p,null,2),(p.title||'Словник')+'.slovnik');notify('Проект скачан вместе со всеми ресурсами.');}
function pickFile(accept,handler){const f=$('#file');f.accept=accept;f.value='';f.onchange=async()=>{if(!f.files[0])return;try{await handler(f.files[0]);}catch(err){notify(err.message||'Не удалось прочитать файл.');}};f.click();}
function loadProject(){pickFile('.slovnik,.json',async file=>{let loaded=validateProject(JSON.parse(await file.text()));commit(()=>p=loaded);render();notify('Проект восстановлен.');});}
async function importWords(){pickFile('.txt,.csv,.json,.xlsx',async file=>{let words;if(file.name.endsWith('.xlsx')){let {readXlsx}=await import('./core/xlsx.js');words=(await readXlsx(await file.arrayBuffer())).map(makeWord);}else if(file.name.endsWith('.json')){let data=JSON.parse(await file.text());let rows=Array.isArray(data)?data:data.words;if(!Array.isArray(rows))throw Error('JSON должен содержать массив слов или поле words.');words=rows.map(row=>typeof row==='string'?makeWord(row):{...makeWord(row.word||''),...row,id:uid(),approved:false}).filter(w=>w.word.trim());}else words=parseText(await file.text());if(!words.length)throw Error('Не найдено слов для импорта.');openDialog('Предпросмотр импорта',`<p>Найдено ${words.length} записей. Пробелы и пустые строки удалены. Совпадающие слова будут пропущены.</p><div class="word-list">${words.slice(0,200).map(w=>`<span class="word-chip">${e(w.word)}</span>`).join('')}</div>`,`<button class="btn primary" id="confirmImport">Добавить слова</button>`);$('#confirmImport').onclick=()=>{appendWords(words);modal.close();};});}
async function fileData(file,optimize=false){if(file.size>20*1024*1024)throw Error('Размер одного файла не должен превышать 20 МБ.');let data=await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file);});if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type))throw Error('Поддерживаются PNG, JPEG, WebP и GIF.');let before=data.length;if(optimize&&file.type!=='image/gif'&&file.type!=='image/webp'){let im=new Image();im.src=data;await im.decode();let scale=Math.min(1,1600/Math.max(im.width,im.height)),canvas=document.createElement('canvas');canvas.width=im.width*scale;canvas.height=im.height*scale;canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);let compressed=canvas.toDataURL('image/webp',.88);if(compressed.length<data.length)data=compressed;}notify(`Ресурс: ${(before*.75/1024).toFixed(0)} → ${(data.length*.75/1024).toFixed(0)} КБ${file.type==='image/gif'?' · GIF сохранён без изменений':''}`);return data;}
function uploadAsset(background){let optimize=$('#optimize')?.checked??true;pickFile('image/png,image/jpeg,image/webp,image/gif',async file=>{let data=await fileData(file,optimize);commit(()=>{if(background)p.background=data;else{let id=uid();p.assets.push({id,name:file.name,data});let o={...newObject(''),assetId:id,x:50,y:60};p.objects.push(o);selected=o.id;}});});}
let cachedCSS;async function gameHTML(compact=false){let css=cachedCSS??=await(await fetch('./game.css')).text();css=css.replace(/@import[^;]+;/g,'');let data=JSON.stringify(p).replace(/</g,'\\u003c');let html=`<!doctype html><html lang="ru"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(p.title)}</title><style>${css}\nhtml,body{margin:0;background:#172c25;min-height:100%;display:grid;place-items:center;width:100%}.game-scene{width:min(100vw,177.77vh);border-radius:0}</style></head><body><main class="game-scene" id="game" aria-label="${e(p.title)}"></main><script>(${mountGame.toString()})(document.getElementById('game'),${data});<\/script></body></html>`;if(compact)html=html.replace(/\/\*[\s\S]*?\*\//g,'').replace(/\n\s*/g,'');return html;}
function exportGate(){let errors=validate(p);if(!errors.length)return true;openDialog('Проверим перед экспортом',`<p>Чтобы ученики получили готовую игру, исправьте следующее:</p>${errors.map(s=>`<div class="rule-error">${e(s)}</div>`).join('')}`,`<button class="btn primary" id="fixTasks">Перейти к заданиям</button>`);$('#fixTasks').onclick=()=>{modal.close();selectTab('tasks');};return false;}
async function downloadGame(compact){if(!exportGate())return;try{download(await gameHTML(compact),(p.title||'Словник')+'.html','text/html');notify('Автономная игра скачана. Можно играть без интернета.');}catch{notify('Не удалось собрать HTML. Попробуйте ещё раз.');}}
async function copyGenially(){if(!exportGate())return;try{let html=await gameHTML(true);let fragment=`<iframe title="${e(p.title)}" style="width:100%;aspect-ratio:16/9;border:0" sandbox="allow-scripts" srcdoc="${e(html)}"></iframe>`;await navigator.clipboard.writeText(fragment);notify('Код iframe скопирован. Вставьте его в Genially.');}catch{notify('Буфер обмена недоступен. Скачайте HTML и используйте ссылку GitHub Pages.');}}
async function lighten(){if(!exportGate())return;let [a,b]=await Promise.all([gameHTML(),gameHTML(true)]);let before=new Blob([a]).size,after=new Blob([b]).size;openDialog('Компактная игра для Genially',`<p>Убраны комментарии и отступы. Изображения сохраняют текущее качество; анимация GIF остаётся нетронутой.</p><div class="notice">До: ${(before/1024).toFixed(1)} КБ → После: ${(after/1024).toFixed(1)} КБ<br>Экономия: ${(100-after/before*100).toFixed(1)}%</div><p>Ограничения Genially зависят от способа вставки. Если iframe с srcdoc не поддерживается, используйте размещённый HTML по ссылке.</p>`,`<button class="btn primary" id="downloadCompact">Скачать компактный HTML</button>`);$('#downloadCompact').onclick=()=>download(b,p.title+'-compact.html','text/html');}
function exportDialog(){selectTab('export');openDialog('Поделитесь приключением','<p>Скачайте самостоятельную игру или подготовьте её для Genially. Редактор и служебный футер останутся за кадром.</p><div class="export-options"><button class="btn primary" id="modalDownload">↓ Скачать HTML-файл</button><button class="btn" id="modalGenially">⌘ Код для Genially</button><button class="btn" id="modalLighten">✧ Облегчить код</button></div>');$('#modalDownload').onclick=()=>{modal.close();downloadGame(false);};$('#modalGenially').onclick=()=>{modal.close();copyGenially();};$('#modalLighten').onclick=()=>{modal.close();lighten();};}
function help(){openDialog('Из словаря — в приключение','<p><b>1.</b> Добавьте слова во вкладке «Словарь».<br><b>2.</b> Выберите возраст, механику и атмосферу.<br><b>3.</b> Откройте «Задания» и проверьте написания.<br><b>4.</b> Перетащите объекты, добавьте свои картинки.<br><b>5.</b> Нажмите «Тест», затем скачайте игру.</p><div class="notice">Словник хранит проекты на этом устройстве. Скачивайте .slovnik для переноса и резервной копии.</div>');}
function embedHelp(){openDialog('Игра в Genially и GitHub Pages','<p>Скачайте автономный HTML и загрузите его в репозиторий GitHub. В Settings → Pages включите публикацию нужной ветки. Откройте опубликованный файл игры.</p><p>В Genially выберите вставку внешнего содержимого и укажите ссылку на HTML. Для ручной вставки используйте:</p><textarea readonly aria-label="Пример iframe">&lt;iframe src="ССЫЛКА_НА_ИГРУ" title="Словарная игра" style="width:100%;aspect-ratio:16/9;border:0"&gt;&lt;/iframe&gt;</textarea><p>Для небольших проектов можно попробовать «Скопировать код Genially». Поддержка srcdoc зависит от ограничений площадки.</p>');}
function newProject(){openDialog('Начать новую историю?','<p>Текущий проект будет заменён. Скачайте его, если хотите вернуться к нему позже.</p>',`<button class="btn" id="backup">Скачать текущий</button><button class="btn primary" id="reset">Создать новый</button>`);$('#backup').onclick=saveProject;$('#reset').onclick=()=>{snapshot();p=initial();selected=null;changed();modal.close();render();};}
document.addEventListener('keydown',ev=>{if(/INPUT|TEXTAREA|SELECT/.test(ev.target.tagName)||modal.open)return;if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='z'){ev.preventDefault();ev.shiftKey?redo():undo();}if(mode==='edit'&&selected){let o=p.objects.find(o=>o.id===selected);if(!o||o.locked)return;if(ev.key==='Delete'||ev.key==='Backspace'){ev.preventDefault();deleteObject();}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(ev.key)){ev.preventDefault();commit(()=>{let d=ev.shiftKey?5:1;o.x=Math.max(0,Math.min(100,o.x+(ev.key==='ArrowRight'?d:ev.key==='ArrowLeft'?-d:0)));o.y=Math.max(0,Math.min(100,o.y+(ev.key==='ArrowDown'?d:ev.key==='ArrowUp'?-d:0)));});}}});
render();try{let saved=await restore();if(saved){saved=validateProject(saved);openDialog('Продолжим вашу историю?','<p>На этом устройстве найден сохранённый проект «'+e(saved.title)+'». Все слова, задания и изображения ждут вас.</p>','<button class="btn" id="fresh">Начать заново</button><button class="btn primary" id="resume">Продолжить редактирование</button>');$('#resume').onclick=()=>{p=saved;modal.close();render();};$('#fresh').onclick=()=>{modal.close();newProject();};}}catch{notify('Автосохранение недоступно. Используйте «Сохранить проект».');}
